<?php
/**
 * Service Worker PHP Wrapper (#81)
 *
 * This file is served as JavaScript but generated by PHP so that
 * the cache version is automatically derived from infoAppVer.php.
 * The .htaccess rule rewrites /service-worker.js → service-worker.js.php.
 *
 * Content-Type is set to JavaScript so the browser treats it correctly.
 *
 * IMPORTANT: This file must ONLY include infoAppVer.php. Including
 * config.php or other files risks PHP errors/warnings that would
 * corrupt the JavaScript output and break service worker registration.
 * CDN URLs are hardcoded here — update them when library versions change.
 */
header('Content-Type: application/javascript; charset=UTF-8');
header('Cache-Control: no-cache, no-store, must-revalidate');
header('Service-Worker-Allowed: /');

/* Hardening (#526) — the file's docblock above warns that PHP errors /
   warnings would corrupt the JS output and break SW registration, but
   previously had no actual handler. If `infoAppVer.php` ever emits a
   notice or a require throws, the SW JS becomes invalid and the
   browser silently fails to register the worker, which silently breaks
   offline mode for every user. Belt-and-braces: trap any error
   *before* it reaches the response, log it, and fall back to a safe
   constant cache key so the SW at least registers (even if the cache
   bucket name is generic). */
$swVersion     = '0.0.0';
$swCommitStamp = '';
$_swPriorErrorHandler = set_error_handler(static function ($severity, $message, $file, $line): bool {
    error_log("[service-worker.php] PHP error during bootstrap: {$message} at {$file}:{$line}");
    return true; /* Suppress — don't allow the warning to leak into the JS body. */
});
try {
    require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'infoAppVer.php';
    $swVersion = $app['Application']['Version']['Number'] ?? '0.0.0';
    /* Fold the commit date (deploy-injected by the GH Actions pipeline) into
       the cache key. Without it every build inside a single semver shares the
       same key and clients stay pinned to the first-installed bundle. Falls
       back to NULL (stripped) during local dev where Commit.Date is unset. */
    $swCommitStamp = preg_replace(
        '/[^0-9]/', '',
        (string)($app['Application']['Version']['Repo']['Commit']['Date'] ?? '')
    );
} catch (\Throwable $e) {
    error_log('[service-worker.php] bootstrap failed; serving SW with generic cache key: ' . $e->getMessage());
} finally {
    /* Restore prior handler (if any) so we don't leak our suppression. */
    restore_error_handler();
}
$swCacheKey = $swCommitStamp !== ''
    ? $swVersion . '-' . $swCommitStamp
    : $swVersion;
?>
/**
 * iHymns — Service Worker
 *
 * Copyright (c) 2026 iHymns. All rights reserved.
 *
 * PURPOSE:
 * Provides offline support and caching for the iHymns PWA.
 *
 * STRATEGY (per-route summary):
 *
 *   ROUTE PATTERN                              STRATEGY
 *   -----------------------------------------  -----------------------------
 *   /                                          network-first (no-store)
 *   /songbooks/, /song/<id>, /tag/<slug>, …    network-first (no-store)
 *   /api?...   (incl. ?page=song, action=*)    network-first (no-store)
 *   /api?action=songs_index (slim index)       conditional revalidation (#1921/#1962, INDEX_CACHE)
 *   CSS / JS / fonts (same-origin)             network-first (no-store)
 *   Trusted CDN (jsdelivr, cdnjs)              network-first (no-store)
 *   /data/audio/*, /data/music/*, /audio/*,
 *     /song-media/<id> (#853)                  cache-first + background
 *                                               revalidation (#1962, MEDIA_CACHE)
 *
 * KEY DESIGN POINT — bypass the browser HTTP cache:
 *
 *   Every network-first branch above uses `fetch(req, { cache: 'no-store' })`
 *   rather than the plain `fetch(req)` it shipped with. Without `no-store`,
 *   the BROWSER'S HTTP CACHE intercepts the request BEFORE the SW gets a
 *   chance to see fresh server data — so a server response with
 *   `Cache-Control: max-age=3600`, OR even a response with NO cache
 *   headers (the browser then heuristic-caches HTML for up to ~10 % of
 *   its age), could be served stale-but-200 to the SW. The SW would
 *   write that stale 200 into its CACHE_VERSION bucket and consider
 *   the round-trip "fresh." Curators on dev.ihymns.app hit this:
 *   after a bulk-import, /songbooks/ kept showing the pre-import list
 *   even after a hard reload AND a manual SW unregister, because the
 *   browser HTTP cache was the real bottleneck.
 *
 *   With `cache: 'no-store'`, the SW always round-trips to the origin
 *   when online. The SW's own CACHE_VERSION bucket remains the single
 *   source of offline-fallback truth — populated only from genuinely
 *   fresh 2xx responses. Media files keep their cache-first strategy
 *   (large binaries, change rarely, so a full re-fetch on every read
 *   would be wasteful) but, since #1962, are no longer trusted FOREVER —
 *   swRevalidateMediaEntry() asks the origin a cheap conditional question
 *   in the background once a cached entry passes MEDIA_REVALIDATE_TTL_MS,
 *   so a curator's re-upload eventually reaches devices that already
 *   saved the old file, without ever forcing a blind re-download.
 *
 * CACHE MANAGEMENT:
 *   - Cache version is derived from infoAppVer.php automatically
 *     (semver × commit-date). Every deploy invalidates older buckets.
 *   - Old caches are automatically cleaned up on activation.
 *   - The dedicated RECENT_CACHE / SAVED_CACHE / MEDIA_CACHE / INDEX_CACHE
 *     buckets all survive version bumps (swKeptCacheNames()) so a user's
 *     downloaded songs, audio and offline search index remain available
 *     across upgrades — see CLAUDE.md rule #6 invariant (A): a deploy must
 *     NEVER evict user-downloaded content.
 *
 * NOTE: This file is generated by PHP (service-worker.js.php) and served
 * via .htaccess rewrite as /service-worker.js. The PHP wrapper injects
 * the current app version into the CACHE_VERSION constant so it always
 * stays in sync with infoAppVer.php (#81).
 */

/* =========================================================================
 * CACHE CONFIGURATION
 * ========================================================================= */

/**
 * Cache LAYOUT revision (#1597).
 *
 * ELI5: a number we bump ourselves whenever we change which boxes the app
 * keeps things in — separate from the app's own version number.
 *
 * Detail: `$swCacheKey` tracks infoAppVer.php (semver × commit date) and is
 * owned by the deploy pipeline. This constant is owned by THIS file and is
 * bumped whenever the SHAPE of the cache changes (a bucket is added, renamed,
 * or its contents start meaning something different), so a layout change
 * invalidates the versioned buckets even inside one deploy. Bumped 1 → 2 for
 * the #1597 split of deliberate downloads out of the recency bucket. Bumped
 * 2 → 3 for #1962: a new version-FREE bucket (INDEX_CACHE) was introduced
 * and the media-caching branch was rewritten (background revalidation,
 * superseded-rendition sweeps, the `/song-media/` URL family) — the SHAPE of
 * what the SW keeps changed, even though MEDIA_CACHE / SAVED_CACHE / the
 * user's own downloaded content are (per invariant A) never renamed and
 * never touched by this bump. Only the two VERSION-KEYED buckets
 * (CACHE_VERSION, PAGES_CACHE) actually get a new name from this — see
 * swKeptCacheNames() and the version-keyed-subset test in
 * tests/test-offline-cache-policy.js.
 */
const SW_CACHE_REVISION = '3';

/**
 * Cache version — derived from the application version AND the deploy-time
 * commit date in infoAppVer.php, plus the layout revision above. The commit
 * date component means every deploy (not just every semver bump) produces a
 * new cache key, so clients pick up fresh module scripts instead of being
 * pinned to the bundle their SW first installed. Old caches are purged on
 * activation (#81).
 */
const CACHE_VERSION = 'ihymns-v<?= $swCacheKey ?>-r' + SW_CACHE_REVISION;

/**
 * Page-fragment cache (#1597 RC3).
 *
 * ELI5: the actual pages — the home screen, the songbook list, a songbook —
 * so you can still move around the app with no signal, not just re-open a
 * song you already had.
 *
 * Detail: before #1597 the SW offline-fell-back ONLY `page=song`, so home /
 * songbooks / songbook / search all 503'd into the red "Failed to load page"
 * card. Even a perfect download was unbrowsable — the only way back to a saved
 * song was history or a bookmark.
 *
 * These fragments are all in api.php's `$_cacheablePages` list, i.e. they are
 * already shared-cache-safe: no per-user data, no per-request nonce (CLAUDE.md
 * rules #6 and #30). The bucket name carries the deploy key so ACTIVATE purges
 * it on every deploy — page markup must never outlive the JS that hydrates it.
 * Contrast RECENT_CACHE / SAVED_CACHE, which deliberately survive deploys
 * because they hold the user's content, not our markup.
 */
const PAGES_CACHE = 'ihymns-pages-v<?= $swCacheKey ?>-r' + SW_CACHE_REVISION;

/**
 * Cap on the page-fragment bucket. `page=search&q=…` is one entry PER QUERY,
 * so without a cap a chatty user grows this without bound inside one deploy
 * window. The trim is confined to this bucket precisely so it can never reach
 * the app shell in CACHE_VERSION (evicting `/js/app.js` to make room for a
 * search result would be a spectacular own goal) — and `swPagesKeysToTrim()`
 * pins the two entry points a user needs in order to browse offline at all.
 */
const PAGES_CACHE_LIMIT = 120;

/**
 * Which `/api?page=…` fragments are worth keeping for offline navigation.
 * Deliberately small: these are the four routes that make a download
 * BROWSABLE. Everything else is either per-user (settings, favourites) or a
 * long tail nobody reaches without a network anyway.
 */
const OFFLINE_PAGE_FRAGMENTS = ['home', 'songbooks', 'songbook', 'search'];

/**
 * Recently-viewed songs cache (#105).
 *
 * ELI5: the last couple of thousand songs you happened to look at. The app
 * tidies this up on its own — oldest out first.
 *
 * Detail: written by the `CACHE_SONG` message router.js posts on EVERY song
 * view. Capped, and trimmed oldest-first on each write. Separate bucket from
 * CACHE_VERSION so it survives app version purges.
 */
const RECENT_CACHE = 'ihymns-recent-songs';
const RECENT_CACHE_LIMIT = 2000;

/**
 * Deliberately-downloaded songs cache (#1597 RC1) — THE fix at the heart of
 * this issue.
 *
 * ELI5: the songs you actually asked to download. They live in their own box
 * that the automatic tidy-up is never allowed to open.
 *
 * Detail: before #1597 bulk downloads and incidental views shared ONE bucket
 * and ONE 2000-entry budget. Download Mission Praise (3,517 songs), then open
 * a single song — the `CACHE_SONG` handler's trim ran and deleted ~1,500
 * entries of the download the UI had just reported as complete. The user found
 * out on a plane.
 *
 * Bulk-saved and recently-viewed are DIFFERENT INTENTS and must not share a
 * cap: a recency cache is a convenience the app may reclaim at will, whereas a
 * download is a promise. So deliberate saves land here and NOTHING in the SW
 * trims this bucket — it shrinks only when the user explicitly asks, via
 * `EVICT_SONGBOOK`, or when the browser evicts the whole origin (which
 * `navigator.storage.persist()` in offline-ui.js now argues against, RC6).
 *
 * Intent is carried on the message: `{ type: 'CACHE_SONG', url, saved: true }`
 * from the Download buttons, and no flag at all from router.js's automatic
 * view-caching — so the DEFAULT stays "recency", and router.js needs no change.
 */
const SAVED_CACHE = 'ihymns-saved-songs';

/**
 * Audio + sheet-music cache (#401).
 *
 * ELI5: the box the actual music files go in.
 *
 * Detail: the name is UNCHANGED from the pre-#1597 tree on purpose. Renaming
 * it would make the very commit that fixes "every deploy wipes your audio"
 * wipe everyone's audio one final time. It was never in the activate keep-list
 * (#1597 RC2), so every SW activation — i.e. every deploy, and the version now
 * bumps on every alpha push (#1596) — deleted the lot while the UI still
 * showed the songbook as saved.
 */
const MEDIA_CACHE = 'iHymns-media-v1';

/**
 * One-time migration marker for the #1597 RECENT → SAVED split.
 * Parked inside SAVED_CACHE so it is naturally scoped to the bucket it
 * describes. Deliberately shaped as a path with NO `id` query parameter, so
 * every consumer that reads a songbook out of a cache key
 * (`swSongbookFromSongCacheUrl`) resolves it to null and skips it — it is
 * never evicted, never counted towards a songbook's size, and never mistaken
 * for a song.
 */
const SAVED_SPLIT_SENTINEL = '/__ihymns_sw__/saved-split-v1';

/**
 * Slim catalogue index cache (#1962 G5).
 *
 * ELI5: its own little box for the offline search index, separate from the
 * app-shell box — so a deploy doesn't force you to re-download the whole
 * song list just to get fresh JS.
 *
 * Detail: before this, `/api?action=songs_index` (WS-I #1017's slim
 * id/number/title/songbook index — the thing search.js falls back to
 * offline) was written into CACHE_VERSION, the versioned app-shell bucket.
 * CACHE_VERSION's name folds in `$swCacheKey`, so it is INTENTIONALLY wiped
 * on every deploy (#81) — but that meant a user who goes offline shortly
 * after an update, before ever completing a fresh online fetch of the
 * index, loses offline search entirely until they're back online once. The
 * index is a few hundred KB and changes only when the catalogue itself
 * does, so — like RECENT_CACHE / SAVED_CACHE / MEDIA_CACHE — it belongs in
 * a bucket that SURVIVES a deploy, with conditional revalidation (already
 * shipped, #1921) doing the "is it stale?" work instead of a deploy-forced
 * wipe. Deliberately version-FREE (no `$swCacheKey` / SW_CACHE_REVISION
 * in the name) so it is never accidentally treated as an app-shell asset;
 * see swKeptCacheNames() and networkFirstRevalidated()'s new `cacheName`
 * parameter.
 * https://developer.mozilla.org/en-US/docs/Web/API/CacheStorage/open
 */
const INDEX_CACHE = 'ihymns-index-v1';

/* =========================================================================
 * CACHE POLICY HELPERS (#1597)
 *
 * Every one of these is PURE — same input, same output, no I/O, no globals
 * beyond `self.location.origin`. That is deliberate: the cache policy is what
 * silently destroyed users' downloads for months, and a pure function is a
 * function `tests/test-offline-cache-policy.js` can call directly. That suite
 * strips the PHP head off this file and evaluates the REAL body, so the test
 * exercises the shipped decision logic rather than a paraphrase of it.
 * ========================================================================= */

/**
 * Every cache bucket that must SURVIVE an activate.
 *
 * ELI5: the list of boxes the spring-clean is not allowed to throw away.
 *
 * Detail: the pre-#1597 activate handler inlined this as
 * `name !== CACHE_VERSION && name !== RECENT_CACHE`, which silently omitted
 * the audio bucket — so every deploy deleted every downloaded MP3 (RC2).
 * Naming the list in one place means a future bucket is added HERE, once,
 * rather than being forgotten in a boolean chain. INDEX_CACHE joined the
 * list in #1962 (G5) for the same reason MEDIA_CACHE did in RC2: it is
 * version-FREE by design (see its own doc-block), so omitting it here would
 * silently wipe the offline search index on every deploy exactly like the
 * RC2 regression did to audio.
 *
 * @returns {string[]}
 */
function swKeptCacheNames() {
    return [CACHE_VERSION, PAGES_CACHE, RECENT_CACHE, SAVED_CACHE, MEDIA_CACHE, INDEX_CACHE];
}

/**
 * Should this cache bucket survive activation?
 * @param {string} name Cache bucket name from caches.keys()
 * @returns {boolean}
 */
function swIsCacheKept(name) {
    return swKeptCacheNames().indexOf(name) !== -1;
}

/**
 * Which bucket does a song page belong in?
 *
 * @param {boolean} [saved] True when the user DELIBERATELY asked to keep this
 *   song (a Download button). Absent/false = incidental view from router.js,
 *   which is the default precisely so router.js needs no change (#1597 RC1).
 * @returns {string} Cache bucket name
 */
function swSongCacheName(saved) {
    return saved === true ? SAVED_CACHE : RECENT_CACHE;
}

/**
 * May this response be written to a Cache-API bucket? (#1769 P3)
 *
 * ELI5: if the server said "don't store this", we don't store it.
 *
 * Detail: the Cache API keys entries by URL alone and cannot evaluate a
 * `Vary: Cookie` header, so a per-viewer response cached under its plain URL
 * would be served to a DIFFERENT viewer of the same device when offline. When
 * content gating is ON, api.php marks the viewer-dependent page=song fragment
 * `Cache-Control: private, no-store` (see api.php $_gatedSongFragment) — this
 * helper honours that so such a fragment is NEVER persisted to PAGES_CACHE /
 * RECENT_CACHE / SAVED_CACHE. DORMANT: with gating off no cacheable-path
 * response carries `no-store`, so every existing put still fires — byte-identical
 * SW behaviour. Missing/blank header ⇒ cacheable (the pre-#1769 default).
 * https://developer.mozilla.org/en-US/docs/Web/API/Cache/put
 *
 * @param {Response} response
 * @returns {boolean} false only when Cache-Control contains `no-store`.
 */
function swResponseCacheable(response) {
    try {
        const cc = (response && response.headers && response.headers.get('Cache-Control')) || '';
        return cc.toLowerCase().indexOf('no-store') === -1;
    } catch (e) {
        return true; /* header unreadable (opaque response) — keep the old behaviour */
    }
}

/**
 * The oldest keys to delete so a bucket fits its cap.
 *
 * ELI5: when the box is too full, take the things that went in first back out.
 *
 * Detail: Cache.keys() resolves in INSERTION order, so `slice(0, excess)` is
 * oldest-first. Callers must only ever hand this the keys of the RECENCY
 * bucket — SAVED_CACHE is never trimmed, which is the whole point of RC1.
 * https://developer.mozilla.org/en-US/docs/Web/API/Cache/keys
 *
 * @param {Array<Request|{url:string}>} keys
 * @param {number} limit
 * @returns {Array} The subset to delete (empty when under the cap)
 */
function swKeysToTrim(keys, limit) {
    const excess = keys.length - limit;
    return excess > 0 ? keys.slice(0, excess) : [];
}

/**
 * The page fragments to delete so the fragment bucket fits its cap.
 *
 * Same oldest-first rule as swKeysToTrim(), except `page=home` and
 * `page=songbooks` are PINNED: they are the two entry points a user needs in
 * order to browse offline at all, and evicting them to make room for the 121st
 * search result would re-create RC3 by the back door.
 *
 * @param {Array<Request|{url:string}>} keys
 * @param {number} limit
 * @returns {Array} The subset to delete
 */
function swPagesKeysToTrim(keys, limit) {
    const excess = keys.length - limit;
    if (excess <= 0) return [];
    const pinned = ['home', 'songbooks'];
    return keys
        .filter(k => pinned.indexOf(swOfflinePageFragment(k && k.url ? k.url : k)) === -1)
        .slice(0, excess);
}

/**
 * Is this URL an `/api?page=…` fragment worth keeping for offline navigation?
 *
 * @param {string} rawUrl Absolute or root-relative URL
 * @returns {string|null} The page name, or null when it isn't one
 */
function swOfflinePageFragment(rawUrl) {
    try {
        const u = new URL(rawUrl, self.location.origin);
        if (!u.pathname.startsWith('/api')) return null;
        const page = u.searchParams.get('page');
        return OFFLINE_PAGE_FRAGMENTS.indexOf(page) !== -1 ? page : null;
    } catch {
        /* A caller can hand us anything the Cache API stored; never throw
           from inside an activate/message handler over a malformed key. */
        return null;
    }
}

/**
 * Songbook abbreviation for a cached SONG PAGE key (`/api?page=song&id=MP-1008`).
 * @param {string} rawUrl
 * @returns {string|null} Upper-cased abbreviation, or null
 */
function swSongbookFromSongCacheUrl(rawUrl) {
    try {
        const id = new URL(rawUrl, self.location.origin).searchParams.get('id') || '';
        const dash = id.indexOf('-');
        return dash > 0 ? id.slice(0, dash).toUpperCase() : null;
    } catch {
        return null;
    }
}

/**
 * Songbook abbreviation for a cached MEDIA key (#1597 RC4).
 *
 * ELI5: works out which songbook an audio file belongs to by reading its
 * filename, because that is where the answer actually is.
 *
 * Detail: the pre-#1597 code matched `/data/audio/<book>/…` SUBDIRECTORIES —
 * a layout this app has never used. `api.php`'s `bulk_audio` emits the FLAT
 * `/data/audio/<SongId>.mp3` (api.php:1517), sheet music is the flat
 * `/data/music/<SongId>.pdf` (sheet-music.js:20), and the gated route is the
 * flat `/audio/<SongId>.mp3?exp=…&sig=…` (#1358). So the directory regex
 * matched NOTHING: "Remove from offline" silently removed no audio at all and
 * the reported size was wrong, both while reporting success.
 *
 * The songbook is recovered from the SongId prefix instead, which CLAUDE.md
 * rule #27 guarantees is `<letters>-<digits>`. The optional directory group is
 * kept so a hypothetical nested layout still resolves.
 *
 * #1962 EXTENSION — the `/song-media/<id>` route (#853): unlike the legacy
 * family above, `<id>` here is an OPAQUE `tblSongMedia.Id` (or an IL id),
 * not a SongId, so there is no prefix to recover from the PATH at all. Per
 * this issue's change to `SongData::_songMediaMap()`, the stamped
 * `streamUrl` instead carries the owning SongId in the QUERY as `?song=`
 * specifically so this attribution still works — see that method's own
 * doc-block. `&v=` (the Sha256-derived cache-buster) plays no part in
 * attribution and is ignored here.
 *
 * @param {string} rawUrl
 * @returns {string|null} Upper-cased abbreviation, or null
 */
function swSongbookFromMediaUrl(rawUrl) {
    let u;
    try {
        u = new URL(rawUrl, self.location.origin);
    } catch {
        return null;
    }
    const pathname = u.pathname;

    /* #1962 — `/song-media/<id>` first: its id is never a SongId, so the
       legacy regex below (which expects `<SongId>.<ext>`) would only ever
       reject it — testing this shape FIRST and returning is cheaper and
       clearer than trying to fold it into that regex. */
    if (/^\/song-media\/[A-Za-z0-9]+$/.test(pathname)) {
        const songParam = u.searchParams.get('song') || '';
        /* Same SongId shape guard as the legacy branch below (rule #27) —
           a missing/malformed `?song=` yields null rather than a guess. */
        if (!/^[A-Za-z0-9]+-\d+$/.test(songParam)) return null;
        return songParam.slice(0, songParam.indexOf('-')).toUpperCase();
    }

    /* /data/audio/… | /data/music/… | /audio/… , an OPTIONAL <dir>/, then
       <basename>.<ext>. The query string is already gone — URL.pathname
       excludes it — so a signed ?exp=…&sig=… URL matches like any other. */
    const m = pathname.match(/^\/(?:data\/audio|data\/music|audio)\/(?:([^/]+)\/)?([^/]+)\.[A-Za-z0-9]+$/);
    if (!m) return null;
    /* Legacy nested layout: the directory IS the songbook. */
    if (m[1]) return m[1].toUpperCase();
    /* Flat layout: derive it from the SongId prefix. rawurlencode() leaves an
       alphanumeric-plus-dash SongId untouched, but decode defensively so an
       escaped key still resolves. */
    let base = m[2];
    try { base = decodeURIComponent(base); } catch { /* keep the raw form */ }
    const dash = base.indexOf('-');
    if (dash <= 0) return null;
    /* Only <letters>-<digits> is a SongId (rule #27); anything else is some
       other file that happens to contain a dash. */
    if (!/^[A-Za-z0-9]+-\d+$/.test(base)) return null;
    return base.slice(0, dash).toUpperCase();
}

/* =========================================================================
 * MEDIA CACHE POLICY (#1962) — cache-first with background revalidation.
 *
 * ELI5: the section above answers "which songbook does this file belong
 * to?"; this section answers the DIFFERENT question "is what's in the
 * cache still good, or should we quietly check for something newer?" for
 * the big binary files (audio, sheet-music PDFs, MusicXML, MIDI).
 *
 * Detail — WHY THIS EXISTS: pre-#1962, the media fetch branch was a plain
 * "serve from cache if present, else fetch-and-cache-forever" with no
 * notion of the file ever changing (see the old branch this replaced,
 * previously at the bottom of the fetch handler, AFTER the navigation
 * branch — that ordering was itself a bug, see swIsMediaUrl()'s doc-block).
 * A curator re-uploading a song's audio (a genuine backend content change)
 * would never reach a device that had already saved the old file, because
 * NOTHING ever asked the origin again. Every helper below is PURE (same
 * input/output, no I/O) except swRevalidateMediaEntry(), which is the ONE
 * function in this section that touches the network/cache — kept as a
 * top-level `async function` specifically so it, too, is directly
 * harvestable/drivable by tests/test-offline-cache-policy.js, matching the
 * rest of this file's testing convention (see the section-241 doc-block
 * above).
 * ========================================================================= */

/**
 * Is this URL a media asset the SW should treat as cache-first-with-
 * background-revalidation, rather than one of the network-first routes
 * above it? (#1962)
 *
 * ELI5: is this a big file — an MP3, a sheet-music PDF — as opposed to a
 * page fragment or a bit of app JS?
 *
 * Detail: matches BOTH media URL families this app emits — see
 * swSongbookFromMediaUrl()'s doc-block for the full shape catalogue:
 *   - legacy static: flat `/data/audio/<SongId>.mp3` /
 *     `/data/music/<SongId>.pdf`, the legacy nested `/data/audio/<book>/…`,
 *     and the #1358 signed `/audio/<SongId>.mp3?exp=…&sig=…` route;
 *   - the #853/#1962 tblSongMedia-backed `/song-media/<id>` route.
 * Deliberately checks the PATH ONLY (never the query string) — a `?v=` /
 * `?exp&sig=` rendition of the same resource must still match.
 * tests/test-offline-media-coverage.js derives its URL samples from every
 * PHP/JS source that actually EMITS a media URL and asserts each one
 * matches here, so a future emit shape this regex doesn't cover goes red
 * rather than silently falling through to the generic asset branch.
 *
 * @param {string} rawUrl
 * @returns {boolean}
 */
function swIsMediaUrl(rawUrl) {
    try {
        const p = new URL(rawUrl, self.location.origin).pathname;
        return /^\/(?:data\/audio|data\/music|audio)\/(?:[^/]+\/)?[^/]+\.[A-Za-z0-9]+$/.test(p)
            || /^\/song-media\/[A-Za-z0-9]+$/.test(p);
    } catch { return false; }
}

/**
 * How long a cached media entry is trusted before the SW bothers asking the
 * origin "has this changed?" in the background (#1962).
 *
 * ELI5: a downloaded song's audio is treated as good for a week before we
 * check again — no point pestering the server on every single play.
 *
 * Detail: purely a "don't check on every single play" throttle, NOT a
 * correctness requirement — invariant (A) (never evict on deploy/activate)
 * is already guaranteed structurally by MEDIA_CACHE surviving `activate`
 * (swKeptCacheNames(), RC2), and invariant (B) (only refresh when content
 * actually changed) is enforced by swRevalidateMediaEntry()'s conditional
 * GET, not by this number. The exact figure is deliberately NOT pinned by
 * value in the test suite (rule #34 — a guard asserting "7 days exactly"
 * would need editing on every tuning pass with zero behavioural stake in
 * the literal number).
 */
const MEDIA_REVALIDATE_TTL_MS = 7 * 24 * 60 * 60 * 1000;

/**
 * URLs currently mid-background-revalidation (#1962).
 *
 * ELI5: don't ask the server "did this change?" twice at once for the same
 * file — e.g. the user taps play/pause/play again before the first check
 * has come back.
 *
 * Detail: keyed on the request URL string. An entry is added immediately
 * before `event.waitUntil(swRevalidateMediaEntry(...))` in the fetch
 * handler and removed in a `.finally()` regardless of outcome (success,
 * 304, or a thrown/offline error), so a transient failure can never wedge a
 * URL out of all FUTURE revalidation attempts.
 * @type {Set<string>}
 */
const inflightMediaRevalidations = new Set();

/**
 * Should a cached media entry be revalidated against the origin right now?
 * (#1962)
 *
 * ELI5: look at the date stamped on the cached copy — missing, or older
 * than the TTL, means "time to check".
 *
 * Detail: `dateHeader` is the CACHED Response's own `Date` header — set by
 * the origin at the moment it was first written to the cache
 * (https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Date; every
 * PHP response the Cache API stores carries one automatically) — never the
 * current wall-clock time, so this answers "how old is what I HAVE", not
 * "when did I last check". A missing or unparseable header (`Date.parse()`
 * → `NaN`) is treated as "revalidate": an entry with no readable Date is
 * the SAFER case to double-check, never the case to skip.
 *
 * @param {string|null} dateHeader
 * @param {number} nowMs
 * @param {number} ttlMs
 * @returns {boolean}
 */
function swMediaShouldRevalidate(dateHeader, nowMs, ttlMs) {
    if (!dateHeader) return true;
    const ts = Date.parse(dateHeader);
    if (Number.isNaN(ts)) return true;
    return (nowMs - ts) >= ttlMs;
}

/**
 * Which keys in MEDIA_CACHE are now SUPERSEDED by a URL just written to the
 * bucket? (#1962)
 *
 * ELI5: if you just saved a fresh copy of a file under a slightly different
 * web address (a new `?v=` fingerprint, or a re-signed link), throw out the
 * OLD address's copy of THAT SAME FILE — never a different file that just
 * happens to live under the same folder.
 *
 * Detail: two cached keys are "the same media, a different rendition" —
 * the shape the #1358 signed-URL rotation and the #1962 `?v=<sha256>`
 * cache-buster both produce — ONLY when their PATHNAMES are identical and
 * their full URLs differ (i.e. only the query string changed).
 * Pathname-only equality is deliberate and load-bearing: `/song-media/9`
 * and `/song-media/12` are two DIFFERENT tblSongMedia rows and must never
 * supersede one another just because they share a path PREFIX — this
 * compares the WHOLE pathname, not a prefix.
 * https://developer.mozilla.org/en-US/docs/Web/API/Cache/keys
 *
 * @param {Array<Request|{url:string}>} keys All current keys in MEDIA_CACHE
 * @param {string} justCachedUrl The URL just written (kept, never returned)
 * @returns {Array} The subset of `keys` to delete
 */
function swMediaSupersededKeys(keys, justCachedUrl) {
    let justPath;
    try {
        justPath = new URL(justCachedUrl, self.location.origin).pathname;
    } catch {
        return [];
    }
    return keys.filter((k) => {
        const url = (k && k.url) ? k.url : k;
        if (url === justCachedUrl) return false; /* the entry we just wrote */
        try {
            return new URL(url, self.location.origin).pathname === justPath;
        } catch {
            return false;
        }
    });
}

/**
 * Extract a conditional-GET validator pair from a cached Response's
 * headers, if it carries one at all (#1962).
 *
 * ELI5: does this saved file have a "fingerprint" (ETag) or a "last
 * touched" date (Last-Modified) we can hand back to the server so it can
 * answer "still current?" without resending the whole file?
 *
 * Detail: song-media.php has stamped a strong ETag off `Sha256` + a
 * Last-Modified off `UpdatedAt` since #1452; audio-media.php gained the
 * matching shape (filesize+filemtime ETag) in #1962. `headersLike` is a
 * real `Headers` instance from a cached Response, so `.get()` is always
 * safe. NEITHER present → `null`, which is the signal
 * `swRevalidateMediaEntry()` uses to skip revalidation ENTIRELY rather than
 * falling back to a blind unconditional refetch — a conditional GET with no
 * validator to send isn't conditional at all.
 * https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/ETag
 * https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Last-Modified
 *
 * @param {Headers} headersLike
 * @returns {{etag: string|null, lastModified: string|null}|null}
 */
function swMediaValidators(headersLike) {
    let etag = null;
    let lastModified = null;
    try { etag = headersLike.get('ETag') || null; } catch { /* unreadable */ }
    try { lastModified = headersLike.get('Last-Modified') || null; } catch { /* unreadable */ }
    if (!etag && !lastModified) return null;
    return { etag, lastModified };
}

/**
 * What should the CACHE_AUDIO_URLS bulk handler do for ONE url, given what
 * (if anything) MEDIA_CACHE already holds for it? (#1962)
 *
 * ELI5: three choices per file in a bulk download — "already have it and
 * nothing to safely ask about, leave it alone"; "have it (or a close
 * cousin under a different `?v=`) and CAN ask the server if it changed";
 * or "have nothing at all, just fetch it".
 *
 * Detail: replaces the pre-#1962 unconditional "skip if ANY cache hit
 * exists, else fetch" rule, which meant a bulk re-download of an
 * already-saved songbook could never pick up a re-uploaded file until the
 * user explicitly evicted and re-saved it — invariant (B) violated in the
 * OTHER direction from the historical #1597 bugs (stuck stale forever,
 * rather than wrongly evicted).
 *
 * @param {boolean} hasExact Whether an EXACT-url cache hit exists.
 * @param {{etag:string|null,lastModified:string|null}|null} validatorsOrNull
 *   The result of swMediaValidators() on whichever cached Response was
 *   found for this url (the exact hit, or else an `ignoreSearch` sibling
 *   rendition) — `null` when nothing was found, OR something was found but
 *   carries no validator at all.
 * @returns {'skip'|'fetch'|'conditional'}
 */
function swMediaBulkPlan(hasExact, validatorsOrNull) {
    if (validatorsOrNull) return 'conditional';
    if (hasExact) return 'skip';
    return 'fetch';
}

/**
 * Background revalidation for ONE media cache entry (#1962) — the I/O half
 * of the swMediaShouldRevalidate() policy decision above.
 *
 * ELI5: quietly ask the server "has this file changed?" using the
 * fingerprint we already have. If it says no, do nothing. If it says yes,
 * swap in the new bytes under the SAME cache key. If we can't reach the
 * server at all, just leave the old copy exactly as it was — the user
 * never sees anything change, break, or even flicker.
 *
 * Detail — WHY A CONDITIONAL GET, NEVER A BLIND REFETCH: invariant (B) of
 * #1962 is "downloaded content refreshes ONLY when that specific backend
 * content changed". An unconditional refetch-and-replace on a timer would
 * violate that the moment the origin has a transient hiccup or serves a
 * byte-different-but-not-really-different response — the conditional GET
 * makes the SERVER (which holds the real Sha256 / mtime) the arbiter of
 * "changed", never the client's clock. `swMediaValidators()` returning
 * `null` is the guard that enforces this: no ETag AND no Last-Modified
 * means there is nothing SAFE to ask conditionally, so this function
 * returns immediately rather than ever degrading to a plain unconditional
 * GET — that fallback would be exactly the blind refetch invariant (B)
 * forbids.
 *
 * `credentials: 'same-origin'` + `cache: 'no-store'` mirror
 * networkFirstRevalidated()'s own reasoning elsewhere in this file: no
 * cookies leak cross-origin, and the browser's OWN HTTP cache must never
 * intercept this request before the conditional headers reach the origin.
 * NO `Range` header is ever attached here — a revalidation asks about the
 * freshness of the WHOLE resource, never a byte window, so a stray `206`
 * can never be misread by the `status === 200` check below as "a full body,
 * safe to cache".
 *
 * A `304` carries no body (RFC 7232 §4.1) and is NEVER written to the
 * cache — the existing entry already IS the answer. Anything else that
 * isn't a clean `200` (403/404/5xx, or a thrown network error) leaves the
 * cached copy completely untouched: this function only ever ADDS
 * confidence, it never subtracts availability — invariant (A) applied to a
 * background task specifically, so a flaky revalidation can never evict
 * what even a full deploy is already forbidden to evict.
 *
 * A top-level `async function` (not inlined into the fetch handler) so
 * tests/test-offline-cache-policy.js can drive it directly against a
 * controllable `cache`/`fetch` sandbox, matching every other `sw*` helper's
 * harvestable-pure-function convention in this file.
 *
 * https://developer.mozilla.org/en-US/docs/Web/HTTP/Conditional_requests
 * https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/304
 * https://developer.mozilla.org/en-US/docs/Web/API/Cache/put
 *
 * @param {Cache} cache The open MEDIA_CACHE
 * @param {string} url The cache key / fetch target
 * @param {Response} cached A CLONE of the cached Response being revalidated
 *   (the caller keeps the original to serve the current request from)
 * @returns {Promise<void>}
 */
async function swRevalidateMediaEntry(cache, url, cached) {
    try {
        const v = swMediaValidators(cached.headers);
        if (!v) return;                          // no validator → nothing safe to do; NEVER blind-refetch
        const h = new Headers();
        if (v.etag) h.set('If-None-Match', v.etag);
        else h.set('If-Modified-Since', v.lastModified);
        const res = await fetch(new Request(url, { headers: h, credentials: 'same-origin' }), { cache: 'no-store' });
        if (res.status === 200 && swResponseCacheable(res)) {
            await cache.put(url, res);           // backend changed → replace IN PLACE, same key
        }
        // 304 → unchanged, keep entry (never cache.put a 304 — bodiless). 403/404/5xx/network → keep cached copy.
    } catch { /* offline / hiccup — cached copy untouched */ }
}

/**
 * Assets to pre-cache during service worker installation.
 * These are the essential app shell files needed for offline access.
 */
const PRECACHE_ASSETS = [
    '/',
    '/css/app.css',
    '/css/accessibility.css',
    '/css/print.css',
    '/js/app.js',
