    '/js/modules/notifications.js',
    '/js/modules/home-page.js',
    '/js/modules/offline-ui.js',
    '/js/modules/entitlements.js',
    '/manifest.json',
    '/assets/favicon.svg',
];

/**
 * Best-effort precache list (#354). Items here are fetched at install
 * time but failures don't block SW activation. Used for URLs that may
 * be slow or unreliable but are valuable to have warm-cached:
 *   - /api?action=songs_index — the SLIM catalogue index (WS-I #1017):
 *     id/number/title/songbook per song, a few hundred KB gzipped (vs the
 *     ~5.7 MB whole-song corpus we used to precache). It lets a user who
 *     installs the PWA, browses only the home page, then goes offline,
 *     still browse + run a basic title/number search (the client-side
 *     offline fallback in search.js). Online, every read is still live;
 *     this index is the OFFLINE-ONLY fallback.
 *
 * We intentionally do NOT put this in PRECACHE_ASSETS (which is strict)
 * because it would fail the entire SW install if the endpoint is slow
 * on the install-tab's network.
 */
const PRECACHE_BEST_EFFORT_ASSETS = [
    '/api?action=songs_index',
];

/**
 * Trusted CDN origins whose resources are cached for offline use.
 * These CDNs serve CORS headers (Access-Control-Allow-Origin: *)
 * so responses can be cached and later served with SRI verification.
 */
const TRUSTED_CDN_ORIGINS = [
    'https://cdn.jsdelivr.net',
    'https://cdnjs.cloudflare.com',
];

/**
 * Critical CDN assets to pre-cache during install for offline app shell.
 * Hardcoded here (not injected from config.php) to avoid any risk of PHP
 * errors corrupting the JS output and breaking SW registration.
 * UPDATE THESE when library versions change in config.php.
 */
const PRECACHE_CDN_ASSETS = [
    'https://cdn.jsdelivr.net/npm/bootstrap@5.3.6/dist/css/bootstrap.min.css',
    'https://cdn.jsdelivr.net/npm/bootstrap@5.3.6/dist/js/bootstrap.bundle.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css',
    'https://cdn.jsdelivr.net/npm/jquery@3.7.1/dist/jquery.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/animate.css/4.1.1/animate.min.css',
];

/**
 * Local vendor fallback paths — pre-cached best-effort.
 * These files are served when CDN resources are unavailable and the
 * CDN cache is also empty (e.g., first offline launch after install).
 */
const PRECACHE_VENDOR_ASSETS = [
    '/vendor/bootstrap/bootstrap.min.css',
    '/vendor/bootstrap/bootstrap.bundle.min.js',
    '/vendor/fontawesome/css/all.min.css',
    '/vendor/jquery/jquery.min.js',
    '/vendor/animate/animate.min.css',
];

/**
 * Auto-update flag for offline songs (#132).
 * When true, the SW silently updates cached songs when changes are detected.
 * When false (default), the SW notifies the client and waits for confirmation.
 * Toggled via SET_AUTO_UPDATE message from the client.
 */
let autoUpdateOfflineSongs = false;

/**
 * In-flight navigation request map (#140).
 * Prevents duplicate fetches when rapid SPA navigation fires multiple
 * fetch events for the same URL concurrently. If a request for a URL
 * is already in-flight, subsequent requests share the same promise.
 * @type {Map<string, Promise<Response>>}
 */
const inflightNavigations = new Map();

/**
 * Send a message to all controlled clients.
 * @param {object} data Message payload
 */
async function notifyClients(data) {
    const clients = await self.clients.matchAll({ type: 'window' });
    clients.forEach(client => client.postMessage(data));
}

/* =========================================================================
 * INSTALL EVENT — Pre-cache essential assets
 * ========================================================================= */

self.addEventListener('install', (event) => {
    console.log('[SW] Installing service worker:', CACHE_VERSION);

    event.waitUntil(
        caches.open(CACHE_VERSION)
            .then(cache => {
                console.log('[SW] Pre-caching app shell assets');

                /* Local assets — must all succeed for install to complete */
                const localPromise = cache.addAll(PRECACHE_ASSETS);

                /*
                 * CDN assets — best effort. Failures are silently ignored so
                 * a CDN outage doesn't block service worker installation.
                 * These will be cached at runtime on the next page load anyway.
                 */
                const cdnPromise = Promise.allSettled(
                    PRECACHE_CDN_ASSETS.map(url =>
                        fetch(url, { mode: 'cors' })
                            .then(resp => {
                                if (resp.ok) return cache.put(url, resp);
                            })
                            .catch(() => console.warn('[SW] CDN precache skipped:', url))
                    )
                );

                /*
                 * Local vendor fallback files — best effort.
                 * These may not exist if the download-vendor script hasn't run.
                 */
                const vendorPromise = Promise.allSettled(
                    PRECACHE_VENDOR_ASSETS.map(path =>
                        fetch(path)
                            .then(resp => {
                                if (resp.ok) return cache.put(path, resp);
                            })
                            .catch(() => {})
                    )
                );

                /*
                 * Best-effort precache (#354) — the slim song index
                 * (WS-I #1017). Failures here MUST NOT block SW install
                 * (otherwise a flaky network at install-time prevents
                 * offline support forever). Cached opportunistically.
                 *
                 * #1962 G5 — written into INDEX_CACHE, NOT the outer
                 * `cache` (CACHE_VERSION), which is a version-KEYED bucket
                 * wiped on every deploy. INDEX_CACHE is deliberately
                 * version-free (see its own doc-block) so the offline
                 * index survives an update instead of needing one more
                 * online visit to be re-earned every single deploy. Mirrors
                 * `pagesPromise` below, which does the same `caches.open()`
                 * -into-its-own-bucket pattern for PAGES_CACHE.
                 */
                const bestEffortPromise = caches.open(INDEX_CACHE).then(indexCache =>
                    Promise.allSettled(
                        PRECACHE_BEST_EFFORT_ASSETS.map(path =>
                            fetch(path)
                                .then(resp => {
                                    if (resp.ok) return indexCache.put(path, resp);
                                })
                                .catch(() => console.warn('[SW] Best-effort precache skipped:', path))
                        )
                    )
                ).catch(() => { /* storage unavailable — nothing to do */ });

                /*
                 * Page fragments (#1597 RC3) — best effort, into their own
                 * versioned bucket.
                 *
                 * ELI5: grab the home screen and the songbook list up front so
                 * a freshly-installed app still works if you go offline before
                 * you have browsed anywhere.
                 *
                 * Detail: without this, a user who installs the PWA, downloads
                 * a songbook from Settings and then boards a plane has never
                 * fetched `/api?page=home` — so the shell loads and the first
                 * fragment request 503s. Failures here must not block install,
                 * same reasoning as the slim index above.
                 */
                const pagesPromise = caches.open(PAGES_CACHE).then(pagesCache =>
                    Promise.allSettled(
                        ['/api?page=home', '/api?page=songbooks'].map(path =>
                            fetch(path)
                                .then(resp => {
                                    if (resp.ok) return pagesCache.put(path, resp);
                                })
                                .catch(() => console.warn('[SW] Page precache skipped:', path))
                        )
                    )
                ).catch(() => { /* storage unavailable — nothing to do */ });

                return Promise.all([
                    localPromise, cdnPromise, vendorPromise, bestEffortPromise, pagesPromise,
                ]);
            })
            .then(() => {
                /*
                 * skipWaiting() policy (#354):
                 *
                 *   - FIRST install (no existing controller) → call
                 *     skipWaiting() immediately so the SW intercepts
                 *     the very first navigation. Without this, a user
                 *     who installs the PWA and reopens it offline
                 *     before any second navigation gets a "no SW + no
                 *     cached fallback" page-load failure.
                 *
                 *   - UPDATE (controller already exists) → stay in the
                 *     "waiting" state and let app.js show its
                 *     "New version available — Refresh" toast. This
                 *     preserves user agency over reloads mid-session
                 *     (no abrupt reload eating unsaved setlist edits)
                 *     while critical fixes still roll out fast on next
                 *     navigation or tab close.
                 *
                 * Detection: self.registration.active === null on
                 * first install, populated on updates.
                 */
                if (self.registration.active === null) {
                    console.log('[SW] First install; calling skipWaiting() to activate immediately');
                    return self.skipWaiting();
                }
                console.log('[SW] Update installed; awaiting user confirmation to activate');
            })
    );
});

/* =========================================================================
 * ACTIVATE EVENT — Clean up old caches
 * ========================================================================= */

/**
 * One-time rescue of downloads made BEFORE the #1597 RECENT/SAVED split.
 *
 * ELI5: songs you downloaded with the old app are sitting in the box that gets
 * tidied up. Move them into the safe box, once, so the fix doesn't arrive too
 * late to help you.
 *
 * Detail: pre-#1597, bulk downloads went into RECENT_CACHE alongside
 * incidental views, so simply shipping the split would leave every existing
 * download still exposed to the trim until the user happened to re-download.
 * We can tell the two apart exactly: the bulk handler has always stamped its
 * synthesised responses with `X-Bulk-Cached: true`, and the Cache API stores
 * response headers verbatim. Anything carrying that header was a deliberate
 * download; anything without it was a view.
 *
 * Guarded by a sentinel so the scan (up to RECENT_CACHE_LIMIT `match()` calls)
 * runs ONCE per device rather than on every deploy. Fully best-effort — a
 * failure here must never stop the SW activating.
 * https://developer.mozilla.org/en-US/docs/Web/API/Cache/put
 *
 * @returns {Promise<number>} How many entries were promoted
 */
async function swMigrateLegacyBulkDownloads() {
    let moved = 0;
    try {
        const saved = await caches.open(SAVED_CACHE);
        if (await saved.match(SAVED_SPLIT_SENTINEL)) return 0;

        const recent = await caches.open(RECENT_CACHE);
        for (const req of await recent.keys()) {
            const resp = await recent.match(req);
            if (!resp || resp.headers.get('X-Bulk-Cached') !== 'true') continue;
            await saved.put(req, resp.clone());
            await recent.delete(req);
            moved++;
        }

        await saved.put(SAVED_SPLIT_SENTINEL, new Response('', {
            status: 200,
            headers: { 'Content-Type': 'text/plain' },
        }));
        if (moved > 0) {
            console.log('[SW] Promoted', moved, 'legacy bulk-downloaded songs to', SAVED_CACHE);
        }
    } catch (error) {
        console.warn('[SW] Legacy download migration skipped:', error && error.message);
    }
    return moved;
}

/**
 * Re-warm each SAVED songbook's `page=songbook` fragment into the fresh
 * PAGES_CACHE on activate (#1962 G4).
 *
 * ELI5: right after an update, quickly re-fetch the "what's in this
 * songbook" page for every songbook you've downloaded, so tapping INTO one
 * of your saved songbooks still works offline even if you haven't happened
 * to open it online since the update landed.
 *
 * Detail: PAGES_CACHE is intentionally VERSIONED — its name folds in
 * `$swCacheKey` + SW_CACHE_REVISION (see its own doc-block above) so stale
 * page markup can never outlive the JS that hydrates it — which means
 * EVERY deploy starts it empty again. SAVED_CACHE (the user's own
 * downloaded SONGS) deliberately survives untouched (RC1/RC2). Between
 * "deploy lands" and "the user next opens THIS PARTICULAR songbook's page
 * online", that songbook's own `page=songbook` fragment would 503 offline
 * even though every individual SONG in it is still fully cached — the
 * download would look broken from the songbook list, even though every
 * song inside it still opens fine. `swSongbookFromSongCacheUrl()` is the
 * SAME helper EVICT_SONGBOOK / GET_CACHE_SIZES already trust to attribute
 * a cached song to its book (rule #22 — one shared attribution helper, not
 * a second regex). Best-effort per songbook via `Promise.all` over
 * individually-guarded fetches: one book's failure (offline install, a
 * flaky network) must never stop the others or fail activation.
 *
 * @returns {Promise<void>}
 */
async function swRewarmSavedSongbookPages() {
    try {
        const saved = await caches.open(SAVED_CACHE);
        const books = new Set();
        for (const req of await saved.keys()) {
            const book = swSongbookFromSongCacheUrl(req.url);
            if (book) books.add(book);
        }
        if (books.size === 0) return;

        const pages = await caches.open(PAGES_CACHE);
        await Promise.all(Array.from(books).map(async (book) => {
            try {
                const url = `/api?page=songbook&id=${encodeURIComponent(book)}`;
                /* `cache: 'no-store'` — same layered-cache-bypass reasoning
                   as every other network-first fetch in this file. */
                const resp = await fetch(url, { cache: 'no-store' });
                if (resp.ok && swResponseCacheable(resp)) {
                    await pages.put(url, resp);
                }
            } catch { /* best-effort — one songbook's failure is not fatal */ }
        }));
    } catch (error) {
        console.warn('[SW] Saved-songbook page re-warm skipped:', error && error.message);
    }
}

self.addEventListener('activate', (event) => {
    console.log('[SW] Activating service worker:', CACHE_VERSION);

    event.waitUntil(
        caches.keys()
            .then(cacheNames => {
                /* Delete every bucket that isn't on the keep-list (#1597 RC2).
                   The keep-list lives in swKeptCacheNames() rather than being
                   inlined here, because when it WAS inlined it quietly omitted
                   the audio bucket and every deploy wiped users' downloaded
                   MP3s while the UI still showed the songbook as saved. */
                return Promise.all(
                    cacheNames
                        .filter(name => !swIsCacheKept(name))
                        .map(name => {
                            console.log('[SW] Deleting old cache:', name);
                            return caches.delete(name);
                        })
                );
            })
            .then(() => {
                /* Take control of all open tabs immediately. Done BEFORE the
                   migration below so control transfer is never delayed by a
                   one-time scan of up to 2000 cache entries. */
                return self.clients.claim();
            })
            .then(() => swMigrateLegacyBulkDownloads())
            /* #1962 G4 — best-effort, after the legacy migration so a
               freshly-promoted download is already in SAVED_CACHE and gets
               its songbook page re-warmed too, on the very activation that
               promoted it. */
            .then(() => swRewarmSavedSongbookPages())
    );
});

/* =========================================================================
 * FETCH EVENT — Network-first strategy with offline fallback
 *
 * Strategy per resource type:
 *   1. Trusted CDNs  → Network-first, cache for offline (Bootstrap, FA, jQuery)
 *   2. Other CDNs    → Network-only (analytics, third-party scripts)
 *   3. API requests  → Network-first, cache song pages for offline (#105)
 *   4. Local assets  → Network-first, cache on success, serve cache if offline
 *   5. Navigation    → Network-first, fall back to cached '/' for offline shell
 * ========================================================================= */

self.addEventListener('fetch', (event) => {
    /* The Cache API only supports GET responses — `cache.put()` on a
     * HEAD / POST / PUT / DELETE / PATCH response throws
     *   TypeError: Failed to execute 'put' on 'Cache':
     *               Request method 'HEAD' is unsupported.
     * Every branch below assumes GET (network-first-with-cache, etc.),
     * so pass non-GET requests straight through to the network without
     * SW interception. The offline-indicator's HEAD probe to
     * /manifest.json (#354 B24, commit 6cfd3c6) is the specific
     * request that surfaced this; any future non-GET probe is now
     * also covered. Background Sync queueing for write requests is
     * handled by the separate 'sync' event handler below, not here. */
    if (event.request.method !== 'GET') return;

    const url = new URL(event.request.url);

    /* --- CDN / Third-party resources --- */
    if (url.origin !== self.location.origin) {
        /*
         * Trusted CDN resources (Bootstrap, Font Awesome, jQuery, etc.)
         * are cached with network-first strategy so the app shell renders
         * offline. These CDNs serve CORS headers, so cached responses
         * remain readable for SRI verification.
         */
        if (TRUSTED_CDN_ORIGINS.some(origin => url.origin === origin)) {
            event.respondWith(networkFirstWithCache(event.request));
            return;
        }
        /* Other third-party resources: let the browser handle normally */
        return;
    }

    /* --- Slim song index (WS-I #1017): conditionally-revalidated, cached to
       the INDEX_CACHE bucket (#1962 G5 — moved off CACHE_VERSION so a
       deploy no longer forces the offline index to be re-earned) so the
       OFFLINE browse/search fallback in search.js can read it. MUST
       precede the generic /api branch below,
       which returns a 503 for non-song-page API calls when offline rather
       than serving the cached index. networkFirstRevalidated() (#1921 SW
       half) sends the previously-cached copy's ETag as If-None-Match, so an
       unchanged catalogue costs a 304 instead of the full few-hundred-KB
       payload — networkFirstWithCache() above has no notion of a validator
       header at all, which is why this route gets its OWN strategy rather
       than reusing that one (see networkFirstRevalidated()'s own doc-block
       for why a server-only ETag would otherwise be a silent no-op here). */
    if (url.pathname === '/api' && url.searchParams.get('action') === 'songs_index') {
        /* #1962 G5 — INDEX_CACHE, not CACHE_VERSION: see that constant's
           own doc-block for why the slim index needs a version-free home. */
        event.respondWith(networkFirstRevalidated(event.request, INDEX_CACHE));
        return;
    }

    /* --- API requests: network-first with cache for song pages (#105, #131)
           and for the navigable page fragments (#1597 RC3) --- */
    if (url.pathname.startsWith('/api')) {
        const isSongPage = url.searchParams.get('page') === 'song';
        const songId = url.searchParams.get('id');
        /* Non-null for home / songbooks / songbook / search — the fragments
           that make an offline download actually browsable. */
        const offlinePage = swOfflinePageFragment(event.request.url);
        /* `cache: 'no-store'` bypasses the browser HTTP cache so the
         * SW's network-first guarantee actually delivers a fresh
         * server response — see networkFirstWithCache() for the full
         * rationale. Otherwise `/api?...` calls could be intercepted
         * by the browser's HTTP cache before the SW sees the round-
         * trip, defeating the "online = fresh" contract. */
        event.respondWith(
            fetch(event.request, { cache: 'no-store' })
                .then(async (response) => {
                    /* Page fragments (#1597 RC3) — refresh the versioned
                       fragment bucket on every online fetch, then keep it
                       under its cap. Nothing here can reach the app shell in
                       CACHE_VERSION or the user's songs in SAVED_CACHE. */
                    if (offlinePage && response.ok && swResponseCacheable(response)) {
                        try {
                            const pages = await caches.open(PAGES_CACHE);
                            await pages.put(event.request, response.clone());
                            const doomed = swPagesKeysToTrim(await pages.keys(), PAGES_CACHE_LIMIT);
                            await Promise.all(doomed.map(k => pages.delete(k)));
                        } catch (error) {
                            /* Storage full / private mode — the page still
                               renders; only the offline copy is lost. */
                            console.warn('[SW] Page fragment cache skipped:', error && error.message);
                        }
                    }

                    /* Cache song page API responses for offline access.
                       #1597 RC1 — a song the user DELIBERATELY downloaded
                       lives in SAVED_CACHE, so update detection has to look
                       there first; otherwise a saved song would silently stop
                       receiving updates and would also get a duplicate copy
                       written into the recency bucket. */
                    if (isSongPage && response.ok && swResponseCacheable(response)) {
                        const saved = await caches.open(SAVED_CACHE);
                        const inSaved = await saved.match(event.request);
                        const cache = inSaved ? saved : await caches.open(RECENT_CACHE);
                        const existing = inSaved || await cache.match(event.request);

                        if (existing) {
                            /* Compare content to detect updates (#131) */
                            const [newBody, oldBody] = await Promise.all([
                                response.clone().text(),
                                existing.text(),
                            ]);

                            if (newBody !== oldBody) {
                                if (autoUpdateOfflineSongs) {
                                    /* Auto-update: silently cache the new version */
                                    await cache.put(event.request, response.clone());
                                    notifyClients({
                                        type: 'SONG_UPDATED',
                                        songId,
                                        auto: true,
                                    });
                                } else {
                                    /* Manual mode: notify user, don't overwrite yet */
                                    notifyClients({
                                        type: 'SONG_UPDATE_AVAILABLE',
                                        songId,
                                        url: event.request.url,
                                    });
                                }
                            }
                            /* If content unchanged, refresh the cache timestamp */
                            else {
                                await cache.put(event.request, response.clone());
                            }
                        } else {
                            /* Not previously cached — just cache it */
                            await cache.put(event.request, response.clone());
                        }
                    }
                    return response;
                })
                .catch(() => {
                    /* Offline: serve the cached copy for anything we cache.
                       `caches.match()` with no `cacheName` searches EVERY
                       bucket, so this finds a song in SAVED_CACHE or
                       RECENT_CACHE and a fragment in PAGES_CACHE without the
                       SW having to guess which one it landed in.
                       https://developer.mozilla.org/en-US/docs/Web/API/CacheStorage/match

                       #1597 RC3 — `offlinePage` is what stops home / songbooks
                       / songbook / search falling through to the 503 below and
                       rendering the red "Failed to load page" card, which is
                       what made even a complete download unbrowsable. */
                    if (isSongPage || offlinePage) {
                        return caches.match(event.request).then(cached => {
                            if (cached) return cached;
                            return new Response(
                                JSON.stringify({ error: 'You appear to be offline.' }),
                                { status: 503, headers: { 'Content-Type': 'application/json' } }
                            );
                        });
                    }
                    return new Response(
                        JSON.stringify({ error: 'You appear to be offline. Please check your connection.' }),
                        { status: 503, headers: { 'Content-Type': 'application/json' } }
                    );
                })
        );
        return;
    }

    /* (The whole-corpus songs_json branch was removed in WS-I #1017 — it was
       unreachable anyway, since the generic /api branch above catches it
       first, and nothing on the client requests the corpus any more. The
       slim index has its own branch ahead of the generic /api one.) */

    /* --- Media (audio / sheet-music / MusicXML / MIDI): cache-first with
       background revalidation (#401, rewritten #1962) ---

       ELI5: once a user plays or views a song, the underlying file — MP3,
       PDF, whatever — gets saved. Next time (including offline) it's
       served straight from the cache with no network round-trip at all.
       Every so often, quietly in the background, we ask the server "did
       this change?" and only replace the file if it actually did — see
       swRevalidateMediaEntry()'s own doc-block above for why that check is
       always conditional, never a blind refetch.

       MUST PRECEDE the navigation branch below (#1962 — this branch used
       to live AFTER it): a browser dispatches an `<a download>` click as a
       `navigate`-mode request, NOT a plain fetch
       (https://developer.mozilla.org/en-US/docs/Web/API/Request/mode).
       With the OLD branch order, the navigation branch claimed that click
       FIRST and cached the binary MP3/PDF straight into CACHE_VERSION —
       the versioned APP-SHELL bucket that gets wiped on every deploy —
       under a fresh key on every single click, silently bloating exactly
       the bucket invariant (A) treats as sacrosanct app code, not
       disposable user media. swIsMediaUrl() covers BOTH URL families this
       app emits — see that helper's own doc-block for the full shape
       catalogue, and tests/test-offline-media-coverage.js for the
       tree-derived proof every emit site is covered.

       #1358 — a signed `/audio/<id>.mp3?exp=…&sig=…` URL EXPIRES, so a
       precached copy remains BEST-EFFORT offline exactly as before this
       rewrite: a fresh navigation re-mints the URL (new query string, new
       cache key) and an expired link served from a stale cache entry still
       403s on a cache-miss refetch. PD / un-gated audio (flat, no query
       string) caches as durably as ever. */
    if (swIsMediaUrl(event.request.url)) {
        event.respondWith(
            caches.open(MEDIA_CACHE).then(async (cache) => {
                const hit = await cache.match(event.request);
                if (hit) {
                    /* Serve the cached copy IMMEDIATELY — the whole point
                       of cache-first — then, only if it has gone stale by
                       the loose TTL above, kick off a background check via
                       event.waitUntil() so the response just returned is
                       NEVER delayed by it. inflightMediaRevalidations stops
                       a rapid double-tap (or two concurrent <audio>
                       Range probes) from firing the SAME conditional GET
                       twice concurrently. */
                    if (swMediaShouldRevalidate(hit.headers.get('Date'), Date.now(), MEDIA_REVALIDATE_TTL_MS)
                        && !inflightMediaRevalidations.has(event.request.url)) {
                        inflightMediaRevalidations.add(event.request.url);
                        event.waitUntil(
                            swRevalidateMediaEntry(cache, event.request.url, hit.clone())
                                .finally(() => inflightMediaRevalidations.delete(event.request.url))
                        );
                    }
                    return hit;
                }
                try {
                    const res = await fetch(event.request);
                    /* `res.status === 200`, NEVER bare `res.ok` (#1962):
                       `.ok` is ALSO true for 206 Partial Content, and an
                       <audio> element's very FIRST request is often a
                       Range probe — cache.put()ing a 206 would store a
                       PARTIAL body under the full-resource key, so the
                       next read (offline or not) would silently serve a
                       truncated file. Only a genuine full 200 is safe to
                       treat as "this is the whole resource". */
                    if (res.status === 200 && swResponseCacheable(res)) {
                        await cache.put(event.request, res.clone());
                        /* #1358/#1962 rendition churn — a re-signed URL
                           re-mints on every navigation and a /song-media/
                           streamUrl's `?v=` changes when the underlying
                           file does, so without this the OLD rendition's
                           entry would sit alongside the new one forever:
                           double-counted by GET_CACHE_SIZES, and a
                           landmine for EVICT_SONGBOOK (same-pathname-only,
                           so it can never touch a DIFFERENT song's entry —
                           see swMediaSupersededKeys()'s own doc-block). */
                        const doomed = swMediaSupersededKeys(await cache.keys(), event.request.url);
                        await Promise.all(doomed.map(k => cache.delete(k)));
                    }
                    return res;
                } catch {
                    /* Offline + not cached — let the media element show its
                       own error UI rather than injecting a PNG/JSON. */
                    return new Response('', { status: 504, statusText: 'Offline' });
                }
            })
        );
        return;
    }

    /* --- Navigation requests: network-first, offline shell fallback --- */
    /* Deduplicates concurrent fetches for the same URL (#140) */
    if (event.request.mode === 'navigate') {
        const navKey = url.pathname + url.search;
        const inflight = inflightNavigations.get(navKey);

        if (inflight) {
            /* Another fetch for this URL is already in-flight — share it */
            event.respondWith(inflight.then(r => r.clone()));
            return;
        }

        /* `cache: 'no-store'` bypasses the browser HTTP cache so a
         * navigation to /songbooks/, /song/<id>, /tag/<slug> etc.
         * always reaches the origin when online. Without this, a
         * server response with `Cache-Control: max-age=N` (or no
         * cache headers at all — browsers heuristic-cache HTML for
         * up to ~10 % of the response's age) could be served from
         * the browser's HTTP cache without the SW seeing fresh
         * content. The SW's CACHE_VERSION bucket remains the offline
         * fallback. */
        const navigationPromise = fetch(event.request, { cache: 'no-store' })
            .then(response => {
                /* Only cache successful (2xx) responses — never cache
                 * redirects (301/302) as that causes infinite redirect
                 * loops when served from cache (#140) */
                if (response.ok) {
                    const clone = response.clone();
                    caches.open(CACHE_VERSION).then(cache => {
                        cache.put(event.request, clone);
                    });
                }
                return response;
            })
            .catch(() => {
                /* Offline — serve cached version, app shell, or branded fallback */
                return caches.match(event.request)
                    .then(cached => cached || caches.match('/'))
                    .then(resp => resp || offlineFallbackResponse());
            })
            .finally(() => {
                inflightNavigations.delete(navKey);
            });

        inflightNavigations.set(navKey, navigationPromise);
        event.respondWith(navigationPromise.then(r => r.clone()));
        return;
    }

    /* (The audio/sheet-music branch that used to live here was moved ABOVE
       the navigation branch and rewritten in #1962 — see swIsMediaUrl()'s
       branch earlier in this handler. Do not re-add a media branch here:
       it would sit BELOW `mode === 'navigate'` again and reproduce the
       exact ordering bug #1962 fixed.) */

    /* --- All other local assets: network-first with cache fallback --- */
    event.respondWith(networkFirstWithCache(event.request));
});

/* =========================================================================
 * HELPER FUNCTIONS
 * ========================================================================= */

/**
 * Self-contained offline fallback page.
 * Shown when the user is offline AND no cached version of the page exists
 * (e.g., first launch of a freshly installed PWA with no network).
 * All styles and assets are inlined so no external requests are needed.
 */
const OFFLINE_FALLBACK_HTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
