/**
 * Return the offline fallback page as a Response.
 * @returns {Response}
 */
function offlineFallbackResponse() {
    return new Response(OFFLINE_FALLBACK_HTML, {
        status: 503,
        statusText: 'Service Unavailable',
        headers: { 'Content-Type': 'text/html; charset=UTF-8' }
    });
}

/**
 * Network-first caching strategy.
 * Tries the network first; on success, caches the response.
 * On failure (offline), serves from cache if available.
 *
 * @param {Request} request The fetch request
 * @returns {Promise<Response>} The response
 */
async function networkFirstWithCache(request) {
    try {
        /* Try network first.
         *
         * `cache: 'no-store'` bypasses the BROWSER'S HTTP cache so the
         * SW's "network-first" promise actually delivers a fresh
         * server response — without it, the browser's own HTTP cache
         * can intercept the request first (per Cache-Control headers
         * the PHP response sends, or defaults like
         * `max-age` from absent headers), and the SW gets handed a
         * stale response that LOOKS fresh. That's the layered-cache
         * trap that surfaced on dev.ihymns.app this session — even
         * after unregistering the SW, curators still saw stale
         * `/songbooks/` because the browser HTTP cache kept serving
         * the old HTML. With `no-store`, the SW always round-trips
         * to the origin when online; the SW's own cache (CACHE_VERSION
         * bucket) remains the single source of offline truth. */
        const networkResponse = await fetch(request, { cache: 'no-store' });

        /* Cache the successful response */
        if (networkResponse.ok) {
            const cache = await caches.open(CACHE_VERSION);
            cache.put(request, networkResponse.clone());
        }

        return networkResponse;

    } catch (error) {
        /* Network failed — try cache */
        const cachedResponse = await caches.match(request);
        if (cachedResponse) {
            return cachedResponse;
        }

        /* Nothing in cache either — show the branded offline page */
        return offlineFallbackResponse();
    }
}

/**
 * Conditional-revalidation network-first strategy (#1921 SW half).
 *
 * ELI5: `networkFirstWithCache()` above always downloads the WHOLE thing
 * again, every time. This does the smarter version for `songs_index`: "tell
 * the server what version I already have (via `If-None-Match`); if it says
 * 'nothing changed' (304), just keep using what I've got — don't even
 * download it again."
 *
 * DETAIL — a DISTINCT function, not a modification of
 * `networkFirstWithCache()`: that function ALSO serves CDN assets and page
 * fragments that carry no ETag at all, so bolting conditional-revalidation
 * onto it would be a behaviour change for every OTHER caller (rule #22's
 * "smallest reusable unit" — a genuinely distinct behaviour is a distinct
 * function).
 *
 * WHY THIS EXISTS AT ALL (#1921 §1.2c — the trap the issue missed): the
 * server-side ETag alone (api.php's #1921 server half) is a SILENT NO-OP
 * for the PWA's primary consumer of this route, because the existing route
 * already fetches with `cache: 'no-store'` — deliberately, to defeat the
 * browser's OWN HTTP cache (the "layered-cache trap" documented on
 * `networkFirstWithCache()` above) — and `no-store` also means the browser
 * never auto-attaches `If-None-Match` for us. Without THIS function, a
 * server-side-only ETag would sit there doing nothing: everything still
 * looks alive (the route still works, the response still has an ETag
 * header), and only a byte-counter would ever notice the 304 never happens
 * — precisely the rule #30/#33 failure class.
 *
 * ORDER IS LOAD-BEARING (mirrors #1921 §A.6's proof obligations):
 *   1. Read whatever is ALREADY cached (and its ETag) FIRST — a fresh
 *      install / a purged cache has no cached copy, so `etag` stays null and
 *      this degrades to a plain conditional-less fetch (identical to
 *      `networkFirstWithCache()`'s behaviour for that request).
 *   2. Attach `If-None-Match` via a NEW `Headers` copied from the request's
 *      own headers (never a fresh empty `Headers()`), so cross-cutting
 *      headers a caller already set — `X-API-Version` / `X-Preferred-Languages`
 *      (`apiFetch()`, CLAUDE.md rule #31) — still reach the server. This also
 *      means a v2-tagged request revalidating against a v1-era cached entry
 *      sends the OLD entry's v1 ETag; the server's version-folded compare
 *      then naturally fails and returns a full v2 200, self-correcting with
 *      no `Vary` gymnastics needed.
 *   3. `cache: 'no-store'` is KEPT — the layered-cache fix stays fixed; this
 *      function only adds a validator header on top of it.
 *   4. A `304` NEVER reaches `cache.put()` (a 304 has no body — writing it
 *      would poison the offline fallback with a bodiless entry). The 304
 *      branch returns the EXISTING cached Response instead.
 *   5. A `200` is written keyed on the ORIGINAL `request` (never the
 *      ETag-carrying clone `req`), so a later `cache.match(request)` still
 *      finds it under the same key the route always used.
 *
 * `cacheName` PARAMETER (#1962 G5): originally hardcoded to CACHE_VERSION,
 * the only caller at the time. That bucket is version-KEYED — wiped on
 * every deploy (#81) — which is correct for markup/JS but wrong for the
 * songs_index payload: a user who goes offline shortly after an update,
 * before ever completing one fresh online fetch of the index post-deploy,
 * lost offline search entirely. The sole current call site now passes the
 * version-FREE INDEX_CACHE (see its own doc-block) instead, and this
 * function no longer assumes which bucket it's revalidating into — a
 * future caller can target its own bucket without a copy-paste fork.
 *
 * @param {Request} request The fetch request (the original, un-modified one).
 * @param {string} cacheName Which Cache Storage bucket to read/write.
 * @returns {Promise<Response>} The fresh 200, the still-valid cached 200 (on
 *   a 304 or a network failure), or the offline fallback.
 */
async function networkFirstRevalidated(request, cacheName) {
    const cache  = await caches.open(cacheName);
    const cached = await cache.match(request);
    const etag   = cached ? cached.headers.get('ETag') : null;

    try {
        let req = request;
        if (etag) {
            /* Copy the request's OWN headers (preserves X-API-Version /
               X-Preferred-Languages) rather than starting from an empty
               Headers() — a new Request is needed at all only because
               Request.headers is otherwise read-only. */
            const h = new Headers(request.headers);
            h.set('If-None-Match', etag);
            req = new Request(request, { headers: h });
        }

        /* cache: 'no-store' — the SAME layered-cache-bypass fix
           networkFirstWithCache() relies on; kept unconditionally here too. */
        const response = await fetch(req, { cache: 'no-store' });

        if (response.status === 304 && cached) {
            /* No body to read, nothing new to store — the cached 200 IS
               the answer. Never cache.put() a 304 (see doc-block point 4). */
            return cached;
        }
        if (response.ok) {
            /* Keyed on the ORIGINAL request (not `req`, which carries the
               throwaway If-None-Match header) so future lookups by the
               plain request URL still find this entry. */
            cache.put(request, response.clone());
        }
        return response;

    } catch (error) {
        /* Network failed — serve the last-known-good cached copy, same
           degrade-to-offline shape as networkFirstWithCache(). */
        if (cached) {
            return cached;
        }
        return offlineFallbackResponse();
    }
}

/* =========================================================================
 * MESSAGE EVENT — Handle SKIP_WAITING from the client (#83)
 *
 * When the user clicks the "Refresh" button in the update notification,
 * the client sends a { type: 'SKIP_WAITING' } message. This tells the
 * waiting service worker to activate immediately, replacing the old one.
 * The client then receives a 'controllerchange' event and reloads.
 * ========================================================================= */

/* =========================================================================
 * BACKGROUND SYNC — offline queue drain (#337, #338)
 *
 * `js/modules/offline-queue.js` registers a Sync tag of the form
 * `ihymns-queue-<type>` whenever the user performs an action while
 * offline (song-request submission, favourite toggle, setlist save).
 * The OS then wakes this SW up on reconnect and dispatches a `sync`
 * event carrying that tag.
 *
 * We don't replay the HTTP request from inside the SW (the payload
 * needs session cookies + may need CSRF tokens that the queue doesn't
 * carry). Instead, we echo a `QUEUE_DRAIN` message to every open
 * client; the page's drain handler owns the real POST. If no client
 * is open, the drain happens next time a page loads via the
 * `navigator.onLine` fallback in offline-queue.js.
 * ========================================================================= */
self.addEventListener('sync', (event) => {
    if (!event.tag || !event.tag.startsWith('ihymns-queue-')) return;
    event.waitUntil((async () => {
        const clients = await self.clients.matchAll({
            includeUncontrolled: true,
            type: 'window',
        });
        for (const c of clients) {
            c.postMessage({ type: 'QUEUE_DRAIN', tag: event.tag });
        }
    })());
});

/* =========================================================================
 * WEB PUSH (#311, wired #1671 F6)
 *
 * ELI5: when the server sends this device a notification, show it — and when
 * the user taps it, open the page it points at, reusing a tab that is already
 * on it rather than piling up new ones.
 *
 * WHY THESE TWO LISTENERS ARE THE WHOLE CLIENT HALF. `tblPushSubscriptions`,
 * `push_subscribe` and `push_unsubscribe` have existed since #311 and NOTHING
 * HAS EVER SENT A PUSH: there was no VAPID keypair, no RFC 8291 payload
 * encryption, and no handler here to receive one. A subscription with no `push`
 * listener is not merely idle — some browsers show a generic "This site has
 * been updated in the background" notification instead, so the user gets an
 * unexplained buzz from an app that never meant to send one.
 *
 * NATIVE fetch IS CORRECT HERE and is the one deliberate exception to rule #31.
 * The service worker is a different global scope with no `localStorage`, its
 * requests are not user-scoped, and `js/utils/api-client.js` is a window-scope
 * module. Importing it here would be the rule misapplied. Neither handler makes
 * a request at all, so the point is moot in practice — it is recorded because
 * the next person to add one here will need it.
 *
 * THE PAYLOAD SHAPE IS A CROSS-FILE AGREEMENT with webPushBuildPayload() in
 * includes/web_push.php: `{kind, title, body, url}`. Nothing in the browser can
 * call that PHP function, so tests/php/test-web-push.php asserts that every key
 * the builder emits is read HERE — a mechanism, not a comment (rule #35).
 *
 * https://developer.mozilla.org/docs/Web/API/ServiceWorkerGlobalScope/push_event
 * https://developer.mozilla.org/docs/Web/API/ServiceWorkerGlobalScope/notificationclick_event
 * ========================================================================= */
self.addEventListener('push', (event) => {
    /* A push with no data is legitimate (a "wake up and go look" ping) and must
       still produce SOMETHING: a browser that is handed a push event whose
       waitUntil resolves without showing a notification may show its own
       generic one, or penalise the origin's future pushes. So the fallback
       below is not defensive noise — it is the required behaviour. */
    let payload = { kind: 'announcement', title: 'iHymns', body: '', url: '/' };
    if (event.data) {
        try {
            const parsed = event.data.json();
            if (parsed && typeof parsed === 'object') {
                payload = {
                    kind:  typeof parsed.kind  === 'string' ? parsed.kind  : 'announcement',
                    title: typeof parsed.title === 'string' && parsed.title ? parsed.title : 'iHymns',
                    body:  typeof parsed.body  === 'string' ? parsed.body  : '',
                    /* Site-relative only. The server already restricts this, but
                       a notification is an attacker-attractive way to send
                       somebody to another origin and the check costs nothing on
                       the receiving side too. */
                    url:   (typeof parsed.url === 'string' && /^\/[^/\\]/.test(parsed.url)) ? parsed.url : '/',
                };
            }
        } catch {
            /* Not JSON — keep the fallback rather than dropping the push. */
        }
    }

    event.waitUntil(self.registration.showNotification(payload.title, {
        body: payload.body,
        /* Paths taken from manifest.json's own icon list, not guessed: the
           assets live at /assets/icon-<size>.png, NOT under an /assets/icons/
           directory. A wrong path here is silent — the notification still
           shows, with the browser's generic globe. */
        icon: '/assets/icon-192.png',
        badge: '/assets/icon-96.png',
        /* Tagging by KIND collapses repeats of the same sort of message rather
           than stacking five identical announcements on a lock screen. */
        tag: 'ihymns-' + payload.kind,
        renotify: false,
        data: { url: payload.url, kind: payload.kind },
    }));
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    const target = (event.notification.data && event.notification.data.url) || '/';

    event.waitUntil((async () => {
        const url = new URL(target, self.location.origin);
        /* Same-origin only — belt and braces after the two checks above,
           because this is the line that actually navigates a window. */
        if (url.origin !== self.location.origin) { return; }

        const clients = await self.clients.matchAll({
            includeUncontrolled: true,
            type: 'window',
        });
        /* Reuse an open tab rather than opening another one. A user who taps
           three notifications over a morning should not end up with three
           copies of the app; focusing the existing window is also what every
           platform's notification guidance expects. */
        for (const c of clients) {
            if (c.url === url.href && 'focus' in c) {
                return c.focus();
            }
        }
        for (const c of clients) {
            if ('navigate' in c && 'focus' in c) {
                await c.focus();
                return c.navigate(url.href);
            }
        }
        if (self.clients.openWindow) {
            return self.clients.openWindow(url.href);
        }
    })());
});

self.addEventListener('message', (event) => {
    if (!event.data) return;

    if (event.data.type === 'SKIP_WAITING') {
        console.log('[SW] Received SKIP_WAITING — activating now');
        self.skipWaiting();
    }

    /*
     * Purge per-user cached content on logout (#1388).
     *
     * ELI5: when you sign out on a shared device, the pages you looked at
     * shouldn't still be sitting in the browser's offline box for the next
     * person.
     *
     * Detail: RECENT_CACHE and PAGES_CACHE are keyed by URL ALONE — they carry
     * no notion of who fetched the entry. `UserAuth.logout()` clears the token
     * and the credential store, but the Cache Storage API is invisible to it
     * (a service worker owns those buckets, and a page cannot reach into them
     * on the SW's behalf). So before this, a signed-out or next user on the
     * same device could still be served a cached fragment fetched under the
     * previous session — and once content gating is enabled (#1590), that
     * fragment may hold lyrics their own tier is not entitled to.
     *
     * Deliberately NOT cleared: CACHE_VERSION (the app shell — identical for
     * everyone, expensive to refetch) and MEDIA_CACHE / SAVED_CACHE (songs the
     * user DELIBERATELY saved for offline use; wiping those on logout would
     * silently destroy a deliberate download, and they are re-gated on next
     * fetch anyway).
     *
     * Fire-and-forget: logout must never block on cache eviction.
     * https://developer.mozilla.org/en-US/docs/Web/API/CacheStorage/delete
     */
    if (event.data.type === 'CLEAR_USER_CACHES') {
        event.waitUntil((async () => {
            for (const name of [RECENT_CACHE, PAGES_CACHE]) {
                try {
                    await caches.delete(name);
                } catch (err) {
                    console.warn('[SW] CLEAR_USER_CACHES failed for', name, err);
                }
            }
            console.log('[SW] Per-user caches cleared on logout');
        })());
    }

    /*
     * Download songs for offline use via bulk API (#359 rewrite).
     *
     * Instead of fetching each song individually (3,612 requests!),
     * we fetch entire songbooks in bulk via /api?action=bulk_songs.
     * Each bulk response contains all rendered HTML for a songbook,
     * which we split into individual cache entries. This reduces
     * thousands of requests to ~6, making the download near-instant
     * on any decent connection.
     *
     * Message format:
     *   { type: 'CACHE_ALL_SONGS', songbooks: ['CP','JP',...] }
     *   OR legacy: { type: 'CACHE_ALL_SONGS', songIds: [...] }
     */
    if (event.data.type === 'CACHE_ALL_SONGS') {
        const songbooks = event.data.songbooks;
        const totalSongs = event.data.totalSongs || 0;

        /* Legacy fallback: if songIds array sent, use old per-song method */
        if (!songbooks && Array.isArray(event.data.songIds)) {
            _downloadSongsLegacy(event.data.songIds);
            return;
        }

        if (!Array.isArray(songbooks) || songbooks.length === 0) return;

        /* Self-invoking async wrapper so a rejection from caches.open(),
           fetch() or cache.put() surfaces as a progress message with an
           error string rather than silently stalling the UI at
           "Downloading <book>…" indefinitely (#452). */
        (async () => {
            let completed = 0;
            let failed = 0;
            const total = totalSongs;

            try {
                /* #1597 RC1 — a bulk download is the definition of a
                   deliberate save, so it goes into SAVED_CACHE, which nothing
                   in this SW ever trims. Before the split it went into the
                   capped recency bucket and the next single song view deleted
                   the overflow. */
                const cache = await caches.open(SAVED_CACHE);

                for (const songbook of songbooks) {
                    notifyClients({
                        type: 'CACHE_ALL_SONGS_PROGRESS',
                        completed, failed, total,
                        status: `Downloading ${songbook}...`,
                    });

                    try {
                        const resp = await fetch(`/api?action=bulk_songs&songbook=${encodeURIComponent(songbook)}`);
                        if (!resp.ok) {
                            failed++;
                            notifyClients({
                                type: 'CACHE_ALL_SONGS_PROGRESS',
                                completed, failed, total,
                                warning: `Skipped ${songbook}: HTTP ${resp.status}`,
                            });
                            continue;
                        }

                        const data = await resp.json();
                        const songs = data.songs || {};
                        const ids = Object.keys(songs);

                        for (const id of ids) {
                            try {
                                const url = `/api?page=song&id=${encodeURIComponent(id)}`;
                                const html = songs[id];
                                const fakeResponse = new Response(html, {
                                    status: 200,
                                    headers: {
                                        'Content-Type': 'text/html; charset=UTF-8',
                                        'X-Bulk-Cached': 'true',
                                    },
                                });
                                await cache.put(url, fakeResponse);
                                completed++;
                            } catch (e) {
                                failed++;
                            }
                        }

                        /* Drop this songbook's entries from the recency bucket
                           now that SAVED_CACHE holds a fresh copy of the whole
                           book (#1597 RC1).
                           WHY IT MATTERS: `caches.match()` searches buckets in
                           CREATION order and returns the FIRST hit, and
                           RECENT_CACHE predates SAVED_CACHE on any upgraded
                           device — so a leftover recency copy would SHADOW the
                           download the user just made and serve them staler
                           HTML offline. One keys() scan per songbook rather
                           than a delete() per song. */
                        try {
                            const recent = await caches.open(RECENT_CACHE);
                            const book = songbook.toUpperCase();
                            for (const req of await recent.keys()) {
                                if (swSongbookFromSongCacheUrl(req.url) === book) {
                                    await recent.delete(req);
                                }
                            }
                        } catch (e) {
                            /* Non-fatal: worst case a duplicate lingers. */
                        }

                        /* #1962 G4 — best-effort warm THIS songbook's
                           `page=songbook` fragment into PAGES_CACHE too, so
                           "browse INTO this songbook" works offline right
                           away, not just "open a song I already viewed".
                           Own try/catch: the SONGS are what the user asked
                           to download and must complete even if this
                           best-effort extra fails (see
                           swRewarmSavedSongbookPages()'s doc-block for the
                           full rationale — this is the same fix applied at
                           download-time instead of activate-time, covering
                           the case where no deploy has happened yet). */
                        try {
                            const pageUrl = `/api?page=songbook&id=${encodeURIComponent(songbook)}`;
                            const pageResp = await fetch(pageUrl, { cache: 'no-store' });
                            if (pageResp.ok && swResponseCacheable(pageResp)) {
                                const pages = await caches.open(PAGES_CACHE);
                                await pages.put(pageUrl, pageResp);
                            }
                        } catch (e) {
                            /* Non-fatal: the song download itself already succeeded. */
                        }
                    } catch (e) {
                        /* Network error for this songbook — surface it so
                           the UI moves on rather than hanging silently. */
                        failed++;
                        notifyClients({
                            type: 'CACHE_ALL_SONGS_PROGRESS',
                            completed, failed, total,
                            warning: `Network error on ${songbook}: ${e && e.message ? e.message : 'unknown'}`,
                        });
                    }

                    notifyClients({
                        type: 'CACHE_ALL_SONGS_PROGRESS',
                        completed, failed, total,
                    });
                }
            } catch (e) {
                /* caches.open() failed (storage quota, private-mode,
                   Safari ITP etc.) — let the UI know instead of
                   pretending to be mid-download forever. */
                notifyClients({
                    type: 'CACHE_ALL_SONGS_PROGRESS',
                    completed, failed, total,
                    error: (e && e.message) ? e.message : 'Cache unavailable',
                    /* #1597 RC5 — `done` is what releases the client's
                       progress bar. Without it this branch left the bar
                       spinning at whatever percentage it had reached, forever,
                       because settings.js only completed on
                       completed + failed >= total. */
                    done: true,
                });
                return;
            }

            /* Final report */
            notifyClients({
                type: 'CACHE_ALL_SONGS_PROGRESS',
                completed, failed, total,
                done: true,
            });
        })();
    }

    /* Legacy per-song download (fallback if bulk not available) */
    async function _downloadSongsLegacy(songIds) {
        const total = songIds.length;
        let completed = 0, failed = 0;
        /* Deliberate download → the untrimmed bucket, same as the bulk path
           above (#1597 RC1).
           #1769 P3 — this is a DELIBERATE per-user save, so it is NOT gated by
           swResponseCacheable(): even when content gating is on (every page=song
           then carries `no-store` because the fragment is viewer-dependent), an
           ENTITLED user must still be able to save their songs offline. The
           no-store gate applies only to the INCIDENTAL caches (PAGES_CACHE +
           RECENT_CACHE in the fetch handler) that could serve one viewer's
           fragment to another; a saved copy is re-gated on the next online fetch
           (#1388 posture). The shared-device case (user A saves, user B reads
           offline) is closed by clearing user caches on login — filed follow-up. */
        const cache = await caches.open(SAVED_CACHE);
        const BATCH = 20;
        for (let i = 0; i < songIds.length; i += BATCH) {
            const batch = songIds.slice(i, i + BATCH);
            await Promise.allSettled(batch.map(async (id) => {
                try {
                    const url = `/api?page=song&id=${encodeURIComponent(id)}`;
                    const r = await fetch(url);
                    if (r.ok) { await cache.put(url, r); completed++; } else { failed++; }
                } catch { failed++; }
            }));
            notifyClients({ type: 'CACHE_ALL_SONGS_PROGRESS', completed, failed, total });
        }
        /* Terminal message carries `done` so the client releases its progress
           bar even if some songs failed (#1597 RC5). */
        notifyClients({ type: 'CACHE_ALL_SONGS_PROGRESS', completed, failed, total, done: true });
    }

    /* Set auto-update preference (#132) */
    if (event.data.type === 'SET_AUTO_UPDATE') {
        autoUpdateOfflineSongs = !!event.data.enabled;
        console.log('[SW] Auto-update offline songs:', autoUpdateOfflineSongs);
    }

    /* Accept a pending song update — cache the fresh version (#131) */
    if (event.data.type === 'UPDATE_SONG_CACHE' && event.data.url) {
        try {
            const cacheUrl = new URL(event.data.url, self.location.origin);
            if (cacheUrl.origin !== self.location.origin) return;
        } catch { return; }

        (async () => {
            try {
                /* Refresh the copy IN PLACE — a song the user downloaded must
                   stay in SAVED_CACHE after an update, or accepting an update
                   would quietly demote it back into the trimmable recency
                   bucket and re-create #1597 RC1 one song at a time. */
                const saved = await caches.open(SAVED_CACHE);
                const cache = (await saved.match(event.data.url))
                    ? saved
                    : await caches.open(RECENT_CACHE);
                const response = await fetch(event.data.url);
                if (response.ok) {
                    await cache.put(event.data.url, response);
                    notifyClients({
                        type: 'SONG_UPDATED',
                        songId: event.data.songId,
                        auto: false,
                    });
                }
            } catch (error) {
                console.warn('[SW] Failed to update cached song:', error.message);
            }
        })();
    }

    /* Pre-cache a batch of audio URLs into MEDIA_CACHE (#401, rewritten #1962).
     * Settings page sends this when the "Include audio in offline
     * downloads" toggle is on — once per songbook covered by the
     * current download, after CACHE_ALL_SONGS has been dispatched.
     * Message: { type: 'CACHE_AUDIO_URLS', urls: [...], songbook: 'XX' }
     *
     * ELI5: for every URL in the batch, figure out whether we already have
     * it (skip), might have an OLDER rendition of it worth asking the
     * server about (a quick "did this change?" check), or have nothing at
     * all (a plain download) — via swMediaBulkPlan(), the SAME policy
     * function the fetch handler's cache-first branch effectively encodes
     * inline. Replaces the pre-#1962 unconditional "skip if ANY cache hit
     * exists" rule, which meant re-running a bulk download of an
     * already-saved songbook could never pick up a re-uploaded audio file —
     * see swMediaBulkPlan()'s own doc-block for the full "why".
     */
    if (event.data.type === 'CACHE_AUDIO_URLS' && Array.isArray(event.data.urls)) {
        const urls = event.data.urls;
        const songbook = event.data.songbook || '';

        caches.open(MEDIA_CACHE).then(async (cache) => {
            let completed = 0, failed = 0;
            const total = urls.length;
            const BATCH = 6;

            /* Writes `res` into `cache` under key `u`, then sweeps any
               now-superseded sibling rendition (an older `?v=`/`?exp&sig=`
               of the SAME pathname) — the same put+sweep pairing the fetch
               handler's media branch performs, factored out here purely
               because it's needed from three branches below (fresh fetch,
               conditional-200, AND the conditional-304-with-a-sibling
               "move the bytes to the new key" case). */
            const putAndSweep = async (u, res) => {
                await cache.put(u, res);
                const doomed = swMediaSupersededKeys(await cache.keys(), u);
                await Promise.all(doomed.map(k => cache.delete(k)));
            };

            for (let i = 0; i < urls.length; i += BATCH) {
                const batch = urls.slice(i, i + BATCH);
                await Promise.allSettled(batch.map(async (u) => {
                    try {
                        const cacheUrl = new URL(u, self.location.origin);
                        if (cacheUrl.origin !== self.location.origin) { failed++; return; }

                        const exact = await cache.match(u);
                        /* `ignoreSearch: true` finds a SIBLING rendition of
                           the same resource under a DIFFERENT query string
                           (an older ?v=/?exp&sig= — #1358/#1962 rendition
                           churn) — only looked up when there's no exact hit,
                           since an exact hit already answers the question.
                           https://developer.mozilla.org/en-US/docs/Web/API/Cache/match */
                        const sibling = exact ? null : await cache.match(u, { ignoreSearch: true });
                        const validatorSource = exact || sibling;
                        const validators = validatorSource ? swMediaValidators(validatorSource.headers) : null;
                        const plan = swMediaBulkPlan(!!exact, validators);

                        if (plan === 'skip') { completed++; return; }

                        if (plan === 'conditional') {
                            const h = new Headers();
                            if (validators.etag) h.set('If-None-Match', validators.etag);
                            else h.set('If-Modified-Since', validators.lastModified);
                            const r = await fetch(
                                new Request(u, { headers: h, credentials: 'same-origin' }),
                                { cache: 'no-store' }
                            );
                            if (r.status === 304) {
                                /* Unchanged. If we were checking a SIBLING
                                   (no exact hit under `u` itself), move the
                                   already-downloaded bytes to the new key —
                                   the content is PROVEN unchanged by the
                                   304, so this re-keys without ever
                                   re-fetching the body. */
                                if (sibling) await putAndSweep(u, sibling.clone());
                                completed++;
                                return;
                            }
                            if (r.status === 200 && swResponseCacheable(r)) {
                                await putAndSweep(u, r.clone());
                                completed++;
                                return;
                            }
                            failed++;
                            return;
                        }

                        /* plan === 'fetch' — nothing cached under this URL
                           or its pathname at all. */
                        const r = await fetch(u);
                        /* status === 200, not bare `.ok` — same 206-poison
                           guard as the fetch handler's media branch above. */
                        if (r.status === 200 && swResponseCacheable(r)) {
                            await putAndSweep(u, r.clone());
                            completed++;
                        } else {
                            failed++;
                        }
                    } catch { failed++; }
                }));
                notifyClients({
                    type: 'CACHE_AUDIO_PROGRESS',
                    songbook, completed, failed, total,
                });
            }
            notifyClients({
                type: 'CACHE_AUDIO_PROGRESS',
                songbook, completed, failed, total, done: true,
            });
        });
    }

    /* Evict every cached entry belonging to one songbook (#401, #1597 RC4).
     * Removes matching entries from BOTH song buckets (RECENT_CACHE and
     * SAVED_CACHE — a "Remove from offline" that left the deliberate download
     * behind would be a lie) and from MEDIA_CACHE.
     *
     * #1597 RC4 — the media sweep previously matched
     * `/data/audio/<songbook>/` SUBDIRECTORIES, a layout this app has never
     * emitted; the real URLs are flat `/data/audio/<SongId>.mp3`. So it
     * matched nothing, removed nothing, and reported success. Both sweeps now
     * go through the shared `swSongbookFrom*Url()` helpers, which are what
     * `tests/test-offline-cache-policy.js` pins.
     * Message: { type: 'EVICT_SONGBOOK', songbook: 'XX' }
     */
    if (event.data.type === 'EVICT_SONGBOOK' && typeof event.data.songbook === 'string') {
        const songbook = event.data.songbook;
        if (!/^[A-Za-z0-9_-]{1,16}$/.test(songbook)) return;
        const book = songbook.toUpperCase();
        (async () => {
            let removed = 0;
            for (const cacheName of [RECENT_CACHE, SAVED_CACHE]) {
                try {
                    const songs = await caches.open(cacheName);
                    for (const req of await songs.keys()) {
                        if (swSongbookFromSongCacheUrl(req.url) === book) {
                            if (await songs.delete(req)) removed++;
                        }
                    }
                } catch {}
            }
            try {
                const media = await caches.open(MEDIA_CACHE);
                for (const req of await media.keys()) {
                    if (swSongbookFromMediaUrl(req.url) === book) {
                        if (await media.delete(req)) removed++;
                    }
                }
            } catch {}
            notifyClients({ type: 'SONGBOOK_EVICTED', songbook, removed });
        })();
    }

    /* Report total bytes cached per songbook across both caches (#401).
     * Returns { type: 'CACHE_SIZES', sizes: { 'CP': 1234567, ... } } to the
     * requesting client. Sizes are summed from Content-Length headers (when
     * present) plus a per-entry fallback estimate for entries without them.
     * Message: { type: 'GET_CACHE_SIZES' }
     */
    if (event.data.type === 'GET_CACHE_SIZES') {
        const client = event.source;
        (async () => {
            const sizes = {};
            const addFor = (songbook, bytes) => {
                sizes[songbook] = (sizes[songbook] || 0) + bytes;
            };
            /* Both song buckets — a download in SAVED_CACHE is exactly the
               thing the user wants a size for (#1597 RC1). */
            for (const cacheName of [RECENT_CACHE, SAVED_CACHE]) {
                try {
                    const songs = await caches.open(cacheName);
                    for (const req of await songs.keys()) {
                        const songbook = swSongbookFromSongCacheUrl(req.url);
                        if (!songbook) continue;   /* incl. the migration sentinel */
                        const resp = await songs.match(req);
                        const len = Number(resp?.headers.get('content-length')) || 4096;
                        addFor(songbook, len);
                    }
                } catch {}
            }
            try {
                /* #1597 RC4 — the flat `/data/audio/<SongId>.mp3` shape the
                   app actually emits. The old subdirectory regex matched no
                   real URL, so every songbook's audio counted as 0 bytes. */
                const media = await caches.open(MEDIA_CACHE);
                for (const req of await media.keys()) {
                    const songbook = swSongbookFromMediaUrl(req.url);
                    if (!songbook) continue;
                    const resp = await media.match(req);
                    const len = Number(resp?.headers.get('content-length')) || 262144;
                    addFor(songbook, len);
                }
            } catch {}
            client?.postMessage({ type: 'CACHE_SIZES', sizes });
        })();
    }

    /* Cache a song page (#105, #1597 RC1).
     *
     * TWO CALLERS, TWO INTENTS:
     *   - router.js posts this on EVERY song view with no `saved` flag. That
     *     is a recency hint: it lands in the capped RECENT_CACHE and the trim
     *     below applies.
     *   - the Download buttons (offline-ui.js, settings.js) post
     *     `saved: true`. That is a promise: it lands in SAVED_CACHE, which
     *     NOTHING here trims.
     *
     * Conflating the two is what made a 3,517-song download evaporate the
     * moment its owner opened a single song. The flag defaults to falsy, so
     * router.js keeps its existing behaviour unchanged.
     */
    if (event.data.type === 'CACHE_SONG' && event.data.url) {
        /* Validate URL origin to prevent cache poisoning */
        try {
            const cacheUrl = new URL(event.data.url, self.location.origin);
            if (cacheUrl.origin !== self.location.origin) return;
        } catch { return; }

        const isDeliberate = event.data.saved === true;
        const targetName = swSongCacheName(isDeliberate);

        caches.open(targetName).then(async (cache) => {
            try {
                const response = await fetch(event.data.url);
                if (!response.ok) return;
                await cache.put(event.data.url, response);

                if (isDeliberate) {
                    /* Drop any recency duplicate so the untrimmed copy is the
                       one `caches.match()` finds. See the bulk path above for
                       why creation order makes this matter. */
                    try {
                        const recent = await caches.open(RECENT_CACHE);
                        await recent.delete(event.data.url);
                    } catch { /* non-fatal */ }
                    /* NO TRIM. This bucket shrinks only on an explicit
                       EVICT_SONGBOOK from the user. */
                    return;
                }

                /* Recency bucket only: evict the oldest entries over the cap. */
                const doomed = swKeysToTrim(await cache.keys(), RECENT_CACHE_LIMIT);
                await Promise.all(doomed.map(k => cache.delete(k)));
            } catch (error) {
                console.warn('[SW] Failed to cache song:', event.data.url, error.message);
            }
        });
    }
});
